#pragma once

#include "ShellTheme.hpp"
#include "slic3r/GUI/Widgets/PopupWindow.hpp"
#include <wx/bitmap.h>

class wxGraphicsContext;
#include <wx/control.h>
#include <wx/weakref.h>
#include <functional>
#include <optional>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// Caret is the chip's own solid disclosure triangle; Down/Up/Right are the
// lighter strokes the menu rows use.
// PanelOpen and PanelClosed are the right pane's two states; PanelLeftOpen
// and PanelLeftClosed mirror the same glyph for the left pane.
enum class HeaderIcon { None, Back, Down, Up, Right, Caret, More, Printer, Monitor, Check, Eye, Lock, Slice, Slicing, Plates, Export, Print, Cancel,
                        PanelOpen, PanelClosed, PanelLeftOpen, PanelLeftClosed };

// Draws a semantic Lucide asset, or the product-specific solid caret/pane state,
// into a graphics context for shell surfaces that paint their own rows.
void draw_header_icon(wxGraphicsContext& gc, HeaderIcon icon, double x, double y, double size, const wxColour& color);

// ChipLeft and ChipRight are the two halves of the printer/filament chip. Each is
// a separate focus target, and each paints its own outer half of one shared
// outline, the way PrimaryLeft/PrimaryRight already split the print action.
enum class HeaderStyle { Quiet, ChipLeft, ChipRight, PrimaryLeft, PrimaryRight, Outline, Menu };

// The surface a button sits on, which a Quiet or Outline button takes as its
// own fill at rest. Canvas is the project header's; Raised is a dialog's.
enum class HeaderSurface { Canvas, Raised };

// A status is a colour plus a word, never a colour alone: the design system
// requires state to be readable without relying on hue.
enum class StatusTone { None, Neutral, Positive, Busy, Warning };

// One dot in a row of filament slots. A faded dot keeps its colour at low
// strength: a slot the current plate does not print with.
struct SlotDot
{
    wxColour colour;
    bool     faded{false};
};

// Everything a menu row can carry beyond its label. Grouped rather than spread
// over a dozen setters because HeaderMenu builds a row in one shot, and a row
// with no decoration should read as exactly that at the call site.
struct HeaderRowDecoration
{
    // Text ahead of everything else on the row, in the label's own face -- a
    // slot's number, which the design reads before the slot's dot.
    wxString lead;
    // Leading dot. Set with a valid colour for a filled swatch; set with an
    // invalid colour for the dashed outline of a colour nobody chose.
    std::optional<wxColour> dot;
    // A row of slot dots before the label, in slot order, then a grey "+n"
    // when slots were folded away. Small dots let many slots fit.
    std::vector<SlotDot> slot_dots;
    wxString             slot_more;
    bool                 small_slot_dots{false};
    // Right-aligned secondary text, in the label role.
    wxString   detail;
    // Draws the detail immediately after the label, separated by a middot,
    // instead of right-aligning it. The chip's nozzle reads as part of one
    // line -- "X1 Carbon · 0.4" -- while staying regular beside the bold
    // printer name, which one text run could not do.
    bool       detail_inline{false};
    // Second line under the label, in text/secondary.
    wxString   sub_label;
    bool       bold{false};
    bool       danger{false};
    bool       check{false};
    HeaderIcon trailing{HeaderIcon::None};
    StatusTone status{StatusTone::None};
    wxString   status_word;
};

// Fork-owned painting, with the same wxEVT_BUTTON contract as native controls.
// Each half of the split action remains a separate keyboard focus target.
class HeaderButton : public wxControl
{
public:
    HeaderButton(wxWindow* parent, const ShellTheme& theme, HeaderStyle style,
                 const wxString& label, HeaderIcon icon);
    void set_dark(bool dark);
    void set_surface(HeaderSurface surface) { m_surface = surface; Refresh(); }
    void set_icon(HeaderIcon icon);
    void set_status(bool visible, bool warning = false);
    void set_detail(const wxString& detail);
    void set_decoration(HeaderRowDecoration decoration);
    // A second, interactive glyph at the row's right end, revealed while the
    // row is hovered or selected. Clicking it -- or right-clicking the row --
    // raises wxEVT_MENU instead of wxEVT_BUTTON, so one row can carry a
    // secondary action without a second focusable control.
    void set_row_action(HeaderIcon icon);
    void set_row_action_label(const wxString& label);
    const wxString& row_action_label() const { return m_row_action_label; }
    bool has_row_action() const { return m_row_action != HeaderIcon::None || !m_row_action_label.empty(); }
    // Raises the row action as though its glyph had been clicked.
    void invoke_row_action();
    const HeaderRowDecoration& decoration() const { return m_decoration; }
    // Caps the label before it ellipsizes, so one long preset name cannot pus

... [2930 characters truncated] ...

or a row that swaps the menu's own
    // contents (a sub-list, a back step) rather than finishing a task.
    bool keeps_open{false};
    // Secondary action at the row's right end. Icon actions appear on hover
    // and keep the popup open for a nested step; text actions can dismiss it.
    HeaderIcon row_action{HeaderIcon::None};
    std::function<void()> invoke_row_action;
    HeaderRowDecoration decoration;
    // The row's window name, which lookups and assistive technology read;
    // empty uses the label. Set when the row draws part of what it says
    // outside the label, as a slot row draws its number. Last, so rows
    // written positionally elsewhere stay as they are.
    wxString name;
    // A visible compact text button at the row's right edge. The row itself
    // can remain non-invokable; keyboard activation invokes the text action.
    wxString row_action_label;
    bool dismisses_on_row_action{false};
};

// A custom view among a menu's rows that takes part in the menu's keyboard
// model -- the filament menu's colour row. The menu moves into it with Up
// from the row below it (or Down from the row above), and out of it again the
// same way; while it is in, Left, Right, Return and Space are the view's.
class HeaderMenuKeyView
{
public:
    virtual ~HeaderMenuKeyView() = default;
    // Shows or hides the view's own focus mark.
    virtual void set_key_focus(bool focused) = 0;
    // Left, Right, Return or Space while the view has the keyboard. Returns
    // false for a key it does not use.
    virtual bool on_menu_key(int key_code) = 0;
    // The child the keyboard is on, for tests and assistive technology.
    virtual wxWindow* key_child() const = 0;
};

// Right-aligned transient menu. The popup owns only presentation; callbacks
// return to the owner after dismissal, never run commands inside mouse capture.
//
// A menu can also replace its own contents in place -- the filament menu's
// slot views do this rather than opening a second popup, so the popup keeps
// its position, its keyboard model, and its dismissal handling.
class HeaderMenu : public PopupWindow
{
public:
    HeaderMenu(wxWindow* parent, const ShellTheme& theme, bool dark,
               std::vector<HeaderMenuItem> items);
    // Which edge of the anchor the popup lines up with: Right opens under a
    // control at the window's right (the header), Left under one at its left
    // (the Plates pane), so a menu never opens toward the window's edge.
    enum class Align { Right, Left };
    void open(HeaderButton& anchor, Align align = Align::Right);
    HeaderButton* selected_item() const { return m_selected < 0 ? nullptr : m_items[m_selected]; }
    // The custom view, when it takes part in the keyboard model, and whether
    // the keyboard is in it now.
    HeaderMenuKeyView* key_view() const;
    bool               key_view_active() const { return m_header_active && key_view() != nullptr; }

    // Swaps the rows for a new set and re-lays out at the same anchor. The
    // width stays put so the popup does not jump as the person types.
    void replace_items(std::vector<HeaderMenuItem> items);
    // A custom view among the rows -- the filament menu's colour row. The
    // builder runs with the popup as parent; nullptr clears it.
    // `after_rows` places the custom view below that many rows, so a step can
    // keep its title/back row at the top where the design puts it.
    void set_header_builder(std::function<wxWindow*(wxWindow*)> builder, int after_rows = 0);
    // Invoked when the popup dismisses for any reason, after the anchor has
    // been released. Used to drop menu-owned state the owner is holding.
    void set_dismiss_listener(std::function<void()> listener) { m_dismissed = std::move(listener); }

    // Dismisses the popup and releases its anchor. Public because closing a
    // menu is a normal thing for an owner (or a test) to ask for; Dismiss()
    // alone would leave the anchor painting its open state.
    void close();

protected:
    void OnDismiss() override;

private:
    void select_item(int index);
    void enter_key_view();
    void leave_key_view();
    void build(std::vector<HeaderMenuItem> items);
    void on_key(wxKeyEvent& event);
    void reposition();

    const ShellTheme& m_theme;
    bool m_dark{false};
    std::vector<HeaderButton*> m_items;
    wxWindow* m_header{nullptr};
    std::function<wxWindow*(wxWindow*)> m_header_builder;
    int m_header_after_rows{0};
    // The first selectable row below the custom view, and whether the
    // keyboard is in the view. The flag survives a rebuild, so a view that
    // rebuilds the menu on Return keeps the keyboard.
    int  m_header_item_index{-1};
    bool m_header_active{false};
    std::function<void()> m_dismissed;
    wxWeakRef<HeaderButton> m_anchor;
    Align m_align{Align::Right};
    bool m_closed{false};
    int m_selected{-1};
    int m_width{0};
};

} // namespace Slic3r::GUI::JusPrin
