void ShellController::on_frame_char_hook(wxKeyEvent& event)
{
    // Ctrl+, on Windows and Linux; the macOS app menu already gives Cmd+, to
    // Preferences.
#ifndef __APPLE__
    if (event.GetModifiers() == wxMOD_CONTROL && event.GetKeyCode() == ',') {
        request_preferences();
        return;
    }
#endif
    event.Skip();
}

